{
  "$schema": "https://opencode.ai/config.json",
  "shell": "/usr/bin/fish",
  "plugin": [
    "@tarquinen/opencode-dcp@latest",
    "opencode-background-agents",
    "opencode-websearch-cited",
    [
      "@zenobius/opencode-skillful",
      {
        "basePaths": [
          "{env:HOME}/.config/opencode/skills",
          "{env:HOME}/.claude/skills",
          "{env:HOME}/.claude/plugins/cache",
          ".opencode/skills"
        ],
        "promptRenderer": "markdown"
      }
    ],
    "@prevalentware/opencode-goal-plugin",
    "opencode-openai-codex-auth",
    [
      "@knikolov/opencode-plugin-simple-memory",
      {
        "autoLoad": true,
        "autoSave": true,
        "contextLimit": 5,
        "contextMaxChars": 1200
      }
    ],
    "opencode-mem"
  ],
  "permission": {
    "*": "allow",
    "bash": {
      "*": "allow",
      "rm *mitmproxy/certs*": "deny",
      "rm *.key*": "deny",
      "*UNIPROXY_DEBUG_RAW*": "deny"
    }
  },
  "lsp": {
    "typescript": {
      "command": [
        "typescript-language-server",
        "--stdio"
      ],
      "extensions": [
        ".ts",
        ".tsx",
        ".js",
        ".jsx",
        ".mjs",
        ".cjs",
        ".mts",
        ".cts"
      ]
    },
    "pyright": {
      "command": [
        "pyright-langserver",
        "--stdio"
      ],
      "extensions": [
        ".py",
        ".pyi"
      ]
    },
    "gopls": {
      "command": [
        "gopls"
      ],
      "extensions": [
        ".go"
      ]
    },
    "rust": {
      "command": [
        "rust-analyzer"
      ],
      "extensions": [
        ".rs"
      ]
    },
    "dockerfile": {
      "command": [
        "docker-langserver",
        "--stdio"
      ],
      "extensions": [
        ".dockerfile"
      ]
    },
    "csharp": {
      "disabled": true
    }
  },
  "experimental": {
    "mcp_timeout": 1200000
  },
  "mcp": {
    "chrome-devtools": {
      "type": "local",
      "command": [
        "/usr/bin/node",
        "{env:HOME}/.config/opencode/node_modules/chrome-devtools-mcp/build/src/bin/chrome-devtools-mcp.js",
        "--autoConnect",
        "--experimentalVision",
        "--experimentalScreencast",
        "--categoryExtensions",
        "--memoryDebugging"
      ],
      "enabled": true,
      "timeout": 1200000
    },
    "context7": {
      "type": "remote",
      "url": "https://mcp.context7.com/mcp",
      "enabled": true
    },
    "gh_grep": {
      "type": "remote",
      "url": "https://mcp.grep.app",
      "enabled": true
    },
    "memory": {
      "type": "local",
      "command": [
        "/usr/bin/node",
        "{env:HOME}/.config/opencode/node_modules/@modelcontextprotocol/server-memory/dist/index.js"
      ],
      "environment": {
        "MEMORY_FILE": "{env:HOME}/.config/opencode/memory.json"
      },
      "enabled": true,
      "timeout": 1200000
    },
    "chrome-direct": {
      "type": "local",
      "command": [
        "/usr/bin/node",
        "{env:HOME}/.config/opencode/node_modules/chrome-devtools-mcp/build/src/bin/chrome-devtools-mcp.js",
        "--browserUrl=http://127.0.0.1:9223",
        "--experimentalVision",
        "--experimentalScreencast",
        "--categoryExtensions",
        "--memoryDebugging"
      ],
      "enabled": true,
      "timeout": 1200000
    },
    "chrome-blackwall": {
      "type": "local",
      "command": [
        "/usr/bin/node",
        "{env:HOME}/.config/opencode/node_modules/chrome-devtools-mcp/build/src/bin/chrome-devtools-mcp.js",
        "--browserUrl=http://127.0.0.1:9224"
      ],
      "enabled": true,
      "timeout": 1200000
    },
    "cdp": {
      "type": "local",
      "command": [
        "{env:HOME}/.bun/bin/bun",
        "{env:HOME}/.config/opencode/bin/cdp-mcp.ts"
      ],
      "environment": {
        "CDP_HUB": "ws://127.0.0.1:9225/hub",
        "CDP_BROWSER": "archlinux-1"
      },
      "enabled": true,
      "timeout": 1200000
    },
    "playwright": {
      "type": "local",
      "command": [
        "/usr/bin/node",
        "{env:HOME}/.config/opencode/node_modules/@playwright/mcp/cli.js"
      ],
      "enabled": true,
      "timeout": 1200000
    },
    "memories": {
      "type": "local",
      "command": [
        "{env:HOME}/.bun/bin/memories",
        "serve"
      ],
      "enabled": true,
      "timeout": 1200000
    }
  },
