fun SessionsScreen(
    onOpenChat: (String) -> Unit,
    vm: SessionsViewModel = hiltViewModel(),
) {
    val state by vm.uiState.collectAsStateWithLifecycle()
    var renaming by remember { mutableStateOf<SessionRow?>(null) }
    var deleting by remember { mutableStateOf<SessionRow?>(null) }

    Scaffold(
        modifier = Modifier.fillMaxSize(),
        topBar = {
            Column(Modifier.statusBarsPadding().padding(horizontal = 16.dp, vertical = 8.dp)) {
                Text("Sessions", style = MaterialTheme.typography.headlineMedium)
                OutlinedTextField(
                    value = state.query,
                    onValueChange = vm::setQuery,
                    label = { Text("Search sessions") },
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                )
                Row(
                    Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Text("Show temporary", style = MaterialTheme.typography.bodySmall)
                    Switch(state.showTemp, vm::setShowTemp)
                }
                state.error?.let { Text(it, color = MaterialTheme.colorScheme.error) }
            }
        },
        floatingActionButton = {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                FloatingActionButton(onClick = { vm.createSession(temp = true, onCreated = onOpenChat) }) {
                    Text("T")
                }
                FloatingActionButton(onClick = { vm.createWithDefaultTemp(onOpenChat) }) {
                    Text("+")
                }
            }
        },
    ) { inner ->
        PullToRefreshBox(
            isRefreshing = state.refreshing,
            onRefresh = vm::refresh,
            modifier = Modifier.padding(inner).navigationBarsPadding().fillMaxSize(),
        ) {
            LazyColumn(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                items(state.rows, key = { it.session.id }) { row ->
                    Card(
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp)
                            .clickable { onOpenChat(row.session.id) },
                    ) {
                        Column(Modifier.padding(16.dp)) {
                            Row(
                                Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                Text(
                                    row.session.title.ifBlank { row.session.id.take(12) },
                                    style = MaterialTheme.typography.titleMedium,
                                )
                                Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                    if (row.temp) Text(
                                        "TEMP",
                                        color = MaterialTheme.colorScheme.secondary,
                                        style = MaterialTheme.typography.labelSmall,
                                    )
                                    Text(
                                        dot(row.busy),
                                        color = dotColor(row.busy),
                                    )
                                }
                            }
                            Text(
                                fmtTime(row.session.updatedAt),
                                style = MaterialTheme.typography.bodySmall,
                            )
                            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                                OutlinedButton(onClick = { renaming = row }) { Text("Rename") }
                                OutlinedButton(onClick = { deleting = row }) { Text("Delete") }
                            }
                        }
                    }
                }
            }
        }
    }

    renaming?.let { row ->
        var title by remember(row.session.id) { mutableStateOf(row.session.title) }
        AlertDialog(
            onDismissRequest = { renaming = null },
            title = { Text("Rename session") },
            text = {
                OutlinedTextField(title, { title = it }, singleLine = true, modifier = Modifier.fillMaxWidth())
            },
            confirmButton = {
                Button(onClick = { vm.rename(row.session.id, title); renaming = null }) { Text("Save") }
            },
            dismissButton = { TextButton(onClick = { renaming = null }) { Text("Cancel") } },
        )
    }
    deleting?.let { row ->
        AlertDialog(
            onDismissRequest = { deleting = null },
            title = { Text("Delete session?") },
            text = { Text("This destroys the session on the server. Cannot be undone.") },
            confirmButton = {
                Button(onClick = { vm.delete(row.session.id); deleting = null }) { Text("Delete") }
            },
            dismissButton = { TextButton(onClick = { deleting = null }) { Text("Cancel") } },
        )
    }
}

private fun dot(b: SessionBusy): String = when (b) {
    SessionBusy.IDLE -> "●"
    SessionBusy.BUSY -> "◉"
    SessionBusy.RETRY -> "◌"
}

@Composable
private fun dotColor(b: SessionBusy) = when (b) {
    SessionBusy.IDLE -> MaterialTheme.colorScheme.outline
    SessionBusy.BUSY -> MaterialTheme.colorScheme.tertiary
    SessionBusy.RETRY -> MaterialTheme.colorScheme.error
}

private fun fmtTime(ms: Long): String =
    if (ms <= 0) "" else DateFormat.getDateTimeInstance(DateFormat.SHORT, DateFormat.SHORT).format(Date(ms))

package dev.opencode.remote.chat

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dagger.hilt.android.lifecycle.HiltViewModel
import dev.opencode.remote.domain.ChatMessage
import dev.opencode.remote.domain.ChatPart
import dev.opencode.remote.domain.ChatRepository
import dev.opencode.remote.domain.OutPart
import dev.opencode.remote.domain.Role
import dev.opencode.remote.domain.SettingsRepository
import java.util.UUID
import javax.inject.Inject
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch

data class ChatUiState(
    val messages: List<ChatMessage> = emptyList(),
    val streamingText: Map<String, String> = emptyMap(),
    val busy: Boolean = false,
    val input: String = "",
    val error: String? = null,
    val offline: Boolean = false,
)

/**
 * H1: thread + streaming + send. Streaming deltas from repo events append into
 * [streamingText] keyed "msgId:partId"; full refresh on session.idle (grapeot rules).
 */
@HiltViewModel
class ChatViewModel @Inject constructor(
    private val chat: ChatRepository,
    private val settings: SettingsRepository,
) : ViewModel() {

    private val _state = MutableStateFlow(ChatUiState())
    val state: StateFlow<ChatUiState> = _state.asStateFlow()

    private var sessionId: String = ""
    private var eventJob: Job? = null
    private var lastFrameAt = 0L

    fun open(id: String) {
        sessionId = id
        load()
        eventJob?.cancel()
        eventJob = viewModelScope.launch {
            chat.events.collect { ev ->
                if (ev.sessionID != null && ev.sessionID != sessionId) return@collect
                lastFrameAt = System.currentTimeMillis()
                when {
                    ev.type == "session.idle" || ev.type == "session.status" -> {
                        clearStreaming()
                        load()
                    }
                    ev.type == "message.part.delta" || ev.type == "message.part.updated" -> {
                        val key = "${ev.messageID}:${ev.partID}"
                        val delta = ev.delta ?: ""
                        if (delta.isNotEmpty()) {
                            _state.value = _state.value.copy(
                                streamingText = _state.value.streamingText + (key to (
                                    (_state.value.streamingText[key] ?: "") + delta
                                    )),
                            )
                        }
                    }
                    ev.type == "session.error" -> {
                        _state.value = _state.value.copy(error = ev.raw.take(300), busy = false)
                    }
                    ev.type.startsWith("session.") || ev.type.startsWith("message.") -> {
                        // Other session/message events → light reconcile (debounced by load()).
                    }
                }
            }
        }
        // Watchdog: no frame >20s while busy → one REST reconcile (grapeot rule).
        viewModelScope.launch {
            while (true) {
                delay(5_000)
                if (_state.value.busy && lastFrameAt != 0L &&
                    System.currentTimeMillis() - lastFrameAt > 20_000
                ) {
                    load()
                    lastFrameAt = System.currentTimeMillis()
                }
            }
        }
    }

    fun setInput(t: String) {
        _state.value = _state.value.copy(input = t)
    }

    fun send() {
        val text = _state.value.input.trim()
        if (text.isEmpty() || _state.value.busy) return
        viewModelScope.launch {
            val agent = settings.settings.first().defaultAgent
            val optimistic = ChatMessage(
                id = "local-" + UUID.randomUUID(),
                role = Role.USER,
                parts = listOf(ChatPart.Text(text)),
                optimistic = true,
            )
            _state.value = _state.value.copy(
                messages = _state.value.messages + optimistic,
                input = "",
                busy = true,
                error = null,
            )
            lastFrameAt = System.currentTimeMillis()
            chat.send(sessionId, listOf(OutPart(type = "text", text = text)), agent)
                .onFailure { err ->
                    _state.value = _state.value.copy(
                        messages = _state.value.messages.filterNot { it.id == optimistic.id },
                        input = text,
                        busy = false,
                        error = err.message,
                    )
                }
        }
    }

    fun abort() {
        viewModelScope.launch {
            chat.abortSession(sessionId)
            _state.value = _state.value.copy(busy = false)
        }
    }

    fun retry() {
        load()
        _state.value = _state.value.copy(error = null)
    }

    private fun load() {
        viewModelScope.launch {
            chat.messages(sessionId).fold(
                onSuccess = { msgs ->
                    _state.value = _state.value.copy(
                        messages = mergeStreaming(msgs),
                        busy = false,
                    )
                },
                onFailure { err ->
                    _state.value = _state.value.copy(
                        busy = false,
                        error = err.message,
                        offline = err.message?.contains("Unable to resolve", ignoreCase = true) == true,
                    )
                },
            )
        }
    }

    private fun clearStreaming() {
        if (_state.value.streamingText.isNotEmpty()) {
            _state.value = _state.value.copy(streamingText = emptyMap())
        }
    }

    /** Overlay streaming tails onto loaded messages so text never flashes (grapeot anti-flash). */
    private fun mergeStreaming(msgs: List<ChatMessage>): List<ChatMessage> {
        val tails = _state.value.streamingText
        if (tails.isEmpty()) return msgs
        return msgs.map { m ->
            val overlay = m.parts.map { p ->
                val key = tails.keys.firstOrNull { it.startsWith(m.id + ":") }
                if (p is ChatPart.Text && key != null) ChatPart.Text(p.text + (tails[key] ?: "")) else p
            }
            m.copy(parts = overlay)
        }
    }

    override fun onCleared() {
        eventJob?.cancel()
    }
}

