   --txt:#e9eef4; --dim:#96a1ad; --acc:#1a73e8; --acc2:#7b5cff; --green:#34d399; --r:14px; }
 * { box-sizing: border-box; }
-html, body { height: 100vh; min-height: 100vh; }
+html, body { height: 100vh; min-height: 100vh; overflow-x: hidden; }
 body { margin: 0; display: flex; flex-direction: column; background: var(--bg); color: var(--txt);
   font: 13px/1.55 system-ui, -apple-system, "Segoe UI", sans-serif; }
 /* header */
 #ident { display: flex; align-items: center; gap: 7px; padding: 9px 10px;
