 .msgwrap:hover .copybelow { opacity: 1; visibility: visible; transition-delay: 0s; }
 .copybelow:hover { filter: brightness(1.4); border-color: var(--acc); transform: scale(1.08); }
 .msg img.thumb { max-width: 100%; border-radius: 9px; margin: 6px 0 2px; display: block; }
