   padding: 0 5px; min-height: 0; }
 .chip .x:hover { color: #ff8080; }
 #attachbtn { background: none; border: 1px solid var(--line); color: var(--txt); border-radius: 9px;
   font-size: 15px; height: 32px; padding: 0 11px; cursor: pointer; min-height: 0;
   display: inline-flex; align-items: center; justify-content: center; }
 #attachbtn:hover { border-color: var(--acc); }
