python3 -c "
import json
spec = json.load(open('/home/scriptkid/.config/.dotfiles/blackwall/opencode/mobile/docs/assets/serve-spec-1.0.0-dev.json'))
schemas = spec['components']['schemas']
for n in ['QuestionInfo', 'QuestionV2Info', 'Model', 'PermissionReplied', 'QuestionReplied']:
    s = schemas.get(n)
    print('====', n, 'FOUND' if s else 'MISSING')
    if s: print(json.dumps(s, indent=1)[:1200])
print('==== prompt paths:')
for p, ops in spec['paths'].items():
    if 'prompt_async' in str(ops) or p in ('/session/{sessionID}/message',):
        for m, op in ops.items():
            if m in ('get','post'):
                body = op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema',{})
                print(p, m, json.dumps(body)[:200])
"

