/** H7: permission card — Once / Always / Reject + terminal line after reply (grinev rule). */
@Composable
fun PermissionCard(
    item: PermissionItem,
    onReply: (PermissionReplyKind) -> Unit,
) {
    Card(
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.tertiaryContainer),
        modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp),
    ) {
        Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
            Text("Permission: ${item.permission}", style = MaterialTheme.typography.titleSmall)
            if (item.patterns.isNotEmpty()) {
                Text(item.patterns.joinToString(", "), style = MaterialTheme.typography.bodySmall)
            }
            item.metadata["filepath"]?.let { Text(it, style = MaterialTheme.typography.bodySmall) }
            if (item.replied != null) {
                Text(
                    when (item.replied) {
                        "once" -> "allowed once ✓"
                        "always" -> "always allowed ✓"
                        "reject" -> "rejected ✕"
                        else -> "answered elsewhere"
                    },
                    style = MaterialTheme.typography.bodySmall,
                )
            } else {
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    OutlinedButton(onClick = { onReply(PermissionReplyKind.REJECT) }) { Text("Reject") }
                    OutlinedButton(onClick = { onReply(PermissionReplyKind.ONCE) }) { Text("Once") }
                    Button(onClick = { onReply(PermissionReplyKind.ALWAYS) }) { Text("Always") }
                }
            }
        }
    }
}

/** AskUserQuestion card — single-tap / multi-select + Done / custom / cancel (grinev rules). */
@Composable
fun QuestionCard(
    item: QuestionItem,
    onSubmit: (List<String>) -> Unit,
    onCancel: () -> Unit,
) {
    var selected by remember(item.id) { mutableStateOf(setOf<String>()) }
    var custom by remember(item.id) { mutableStateOf("") }
    var showCustom by remember(item.id) { mutableStateOf(false) }
    Card(
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.secondaryContainer),
        modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp),
    ) {
        Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
            Text(item.header, style = MaterialTheme.typography.titleSmall)
            Text(item.question, style = MaterialTheme.typography.bodyMedium)
            item.options.forEach { opt ->
                val on = opt.label in selected
                FilterChip(
                    selected = on,
                    onClick = {
                        if (!item.multiple) {
                            onSubmit(listOf(opt.label))
                        } else {
                            selected = if (on) selected - opt.label else selected + opt.label
                        }
                    },
                    label = { Text(opt.label) },
                )
                if (opt.description.isNotBlank()) {
                    Text(opt.description, style = MaterialTheme.typography.bodySmall)
                }
            }
            if (item.customAllowed && !showCustom) {
                TextButton(onClick = { showCustom = true }) { Text("Custom answer") }
            }
            if (showCustom) {
                OutlinedTextField(
                    value = custom,
                    onValueChange = { custom = it },
                    label = { Text("Custom") },
                    modifier = Modifier.fillMaxWidth(),
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text),
                )
            }
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                if (item.multiple) {
                    Button(
                        onClick = {
                            val answers = selected.toList() + (custom.takeIf { it.isNotBlank() }?.let { listOf(it) } ?: emptyList())
                            onSubmit(answers)
                        },
                        enabled = selected.isNotEmpty() || custom.isNotBlank(),
                    ) { Text("Done") }
                } else if (showCustom) {
                    Button(onClick = { onSubmit(listOf(custom)) }, enabled = custom.isNotBlank()) {
                        Text("Send custom")
                    }
                }
                TextButton(onClick = onCancel) { Text("Cancel") }
            }
        }
    }
}

