            Text(item.header, style = MaterialTheme.typography.titleSmall)
            Text(item.question, style = MaterialTheme.typography.bodyMedium)
            item.options.forEach { opt ->
                val on = opt.label in selected
                FilterChip(
                    selected = on,
                    onClick = {
                        if (!item.multiple) {
                            onSubmit(listOf(opt.label))
                        } else {
                            selected = if (on) selected - opt.label else selected + opt.label
                        }
                    },
                    label = { Text(opt.label) },
                )
                if (opt.description.isNotBlank()) {
                    Text(opt.description, style = MaterialTheme.typography.bodySmall)
                }
            }
            if (item.customAllowed && !showCustom) {
                TextButton(onClick = { showCustom = true }) { Text("Custom answer") }
            }
            if (showCustom) {
                OutlinedTextField(
                    value = custom,
                    onValueChange = { custom = it },
                    label = { Text("Custom") },
                    modifier = Modifier.fillMaxWidth(),
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text),
                )
            }
            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                if (item.multiple) {
                    Button(
                        onClick = {
                            val answers = selected.toList() + (custom.takeIf { it.isNotBlank() }?.let { listOf(it) } ?: emptyList())
                            onSubmit(answers)
                        },
                        enabled = selected.isNotEmpty() || custom.isNotBlank(),
                    ) { Text("Done") }
                } else if (showCustom) {
                    Button(onClick = { onSubmit(listOf(custom)) }, enabled = custom.isNotBlank()) {
                        Text("Send custom")
                    }
                }
                TextButton(onClick = onCancel) { Text("Cancel") }
            }
        }
    }
}

