 <!doctype html>
 <html>
 <head><meta charset="utf-8"><style>
 :root { color-scheme: dark; --bg:#0a0c0f; --card:#12161c; --line:#222b35;
   --txt:#e9eef4; --dim:#96a1ad; --acc:#1a73e8; --acc2:#7b5cff; --green:#34d399; --r:14px; }
 * { box-sizing: border-box; }
 html, body { height: 100vh; min-height: 100vh; overflow-x: hidden; }
 body { margin: 0; display: flex; flex-direction: column; background: var(--bg); color: var(--txt);
   font: 13px/1.55 system-ui, -apple-system, "Segoe UI", sans-serif; }
 /* header */
 #ident { display: flex; align-items: center; gap: 7px; padding: 9px 10px;
   border-bottom: 1px solid var(--line); flex: none; }
 #dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green);
   box-shadow: 0 0 7px var(--green); flex: none; }
 #dot.busy { background: var(--acc); box-shadow: 0 0 7px var(--acc); animation: pulse 1.2s infinite; }
 @keyframes pulse { 50% { opacity: .45; } }
 #dot { cursor: default; }
 #dotwrap { display: inline-flex; flex: none; }
 #bname { font-weight: 700; font-size: 13px; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
 .iconbtn { background: linear-gradient(135deg, var(--acc), var(--acc2));
   -webkit-background-clip: text; background-clip: text; color: transparent;
   border: 1px solid transparent; border-radius: 9px;
   font-size: 18px; font-weight: 900; line-height: 1; padding: 0; width: 32px; height: 30px;
   cursor: pointer; min-height: 0;
   display: inline-flex; align-items: center; justify-content: center; flex: none;
   transition: transform .18s ease, border-color .18s ease, background-color .18s ease, filter .18s ease; }
 .iconbtn:hover { color: transparent; border-color: var(--line); background-color: var(--card);
   filter: brightness(1.35); transform: scale(1.08); }
 /* context meter */
 #ctxbar { flex: none; padding: 9px 12px 8px; border-bottom: 1px solid var(--line); }
 #ctxbar .track { height: 14px; border-radius: 8px; background: #1a212b; overflow: hidden;
   position: relative; box-shadow: inset 0 1px 3px rgba(0,0,0,.55); }
 #ctxbar .fill { height: 100%; width: 0%; border-radius: 8px; position: relative; overflow: hidden;
   background: linear-gradient(90deg, #1a73e8, #4d8dff 30%, #7b5cff 60%, #34d399);
   box-shadow: 0 0 12px rgba(90,120,255,.6); transition: width .4s ease; }
 #ctxbar .fill::after { content: ""; position: absolute; inset: 0;
   background: linear-gradient(100deg, transparent 20%, rgba(255,255,255,.35) 50%, transparent 80%);
   animation: shimmer 2.6s linear infinite; }
 @keyframes shimmer { from { transform: translateX(-100%); } to { transform: translateX(100%); } }
 #ctxbar .lbl { display: flex; gap: 8px; margin-top: 7px; }
 #ctxbar .pill { font-size: 11px; font-weight: 700; color: #d7e1ec;
   background: linear-gradient(180deg, #1c2530, #141a22);
   border: 1px solid #2c3743; border-radius: 20px; padding: 3px 11px;
   font-variant-numeric: tabular-nums; white-space: nowrap; }
 #ctxbar .pill b { color: var(--acc2); font-weight: 700; margin-right: 4px; }
 #ctxbar .pill.hot { border-color: var(--amber); color: var(--amber); }
 /* chat */
 #chat { flex: 1; display: flex; flex-direction: column; min-height: 0; padding: 10px 12px 0; overflow: hidden; }
 #composer { margin-top: auto; }
 #msgs { flex: 1; display: flex; flex-direction: column; gap: 8px; overflow-y: auto;
   margin: 2px 0 10px; min-height: 60px; }
 #msgs:empty { display: none; }
 .msg { border-radius: 13px; padding: 7px 11px; font-size: 13px; white-space: pre-wrap; word-break: break-word;
   width: fit-content; max-width: 88%; }
 .iconbtn.small-txt { font-size: 11px; font-weight: 700; letter-spacing: .3px; }
 .msg.user { background: linear-gradient(135deg, #1c4587, #3b2f7a 60%, #2b2560); align-self: flex-end;
   box-shadow: 0 4px 16px rgba(30,80,180,.25); }
 .msg.asst { background: linear-gradient(180deg, #161c24, #10141b); border: 1px solid #26303c; align-self: flex-start;
   box-shadow: 0 4px 14px rgba(0,0,0,.3); }
 .msg .meta { font-size: 10px; color: var(--dim); margin-top: 3px; }
 /* message wrapper reserves the copy-button slot so hover never reflows layout */
 .msgwrap { position: relative; display: flex; flex-direction: column; margin-bottom: 42px; }
 .msgwrap:last-child { margin-bottom: 2px; }
 .msgwrap.u { align-items: flex-end; }
 .msgwrap.a { align-items: flex-start; }
 .msgwrap .msg { align-self: auto; }
 /* copy button sits UNDER the bubble (absolute, out of flow), appears on wrap hover */
 .copybelow { position: absolute; bottom: -38px; display: inline-flex; align-items: center; justify-content: center;
   width: 32px; height: 30px; min-height: 0; line-height: 1;
   background: rgba(255,255,255,.07); border: 1px solid var(--line); border-radius: 10px;
   color: #fff; padding: 0;
   cursor: pointer; opacity: 0; visibility: hidden;
   transition: opacity .35s ease, visibility 0s linear 1.2s, filter .3s ease, border-color .3s ease, transform .3s ease; }
 .copybelow svg { display: block; }
 .msgwrap.u .copybelow { right: 2px; }
 .msgwrap.a .copybelow { left: 2px; }
 .msgwrap:hover .copybelow { opacity: 1; visibility: visible; transition-delay: 0s; }
 .copybelow:hover { filter: brightness(1.4); border-color: var(--acc); transform: scale(1.08); }
 .msg img.thumb { max-width: 100%; border-radius: 9px; margin: 6px 0 2px; display: block; }
