                     var tout = 0L
                     var cost = 0.0
                     msgs.forEach { m ->
                         m.parts.forEach { p ->
                             if (p is ChatPart.StepFinish) {
                                 tin += p.input
                                 tout += p.output
                                 cost += p.cost
                             }
